const wall_matrix = [[S_stone, S_tlcorn, S_trcorn, S_hwall, S_tdwall], [S_stone, S_trcorn, S_brcorn, S_vwall, S_tlwall], [S_stone, S_brcorn, S_blcorn, S_hwall, S_tuwall], [S_stone, S_blcorn, S_tlcorn, S_vwall, S_trwall]];
